import { readFile, writeFile } from 'node:fs/promises'
import openapiTS, { astToString } from 'openapi-typescript'

// Snapshot of the game-details endpoints from SwaggerHub 0.2.0-design.
const input = new URL('../src/api-types/player-game.openapi.json', import.meta.url)
const output = new URL('../src/api-types/player-game.generated.ts', import.meta.url)
const schema = JSON.parse(await readFile(input, 'utf8'))
const ast = await openapiTS(schema)
await writeFile(
  output,
  '// Generated by scripts/gen-player-game-api.mjs. Do not edit by hand.\n' + astToString(ast),
)
